window.docContents[34].resolve({"/Slang/#Hoare-Logic--Slang___-Arithmetic-and-Boolean-Expressions--Arithmetic-and-Boolean-Expressions--Optimization":{"contents":"\n\nnamespace Aexp\n\ndef optimize0plus (a : Aexp) : Aexp :=\n  match a with\n  | num   n          => num n\n  | plus  (num 0) e₂ => optimize0plus e₂\n  | plus  e₁      e₂ => plus  (optimize0plus e₁) (optimize0plus e₂)\n  | minus e₁      e₂ => minus (optimize0plus e₁) (optimize0plus e₂)\n  | mult  e₁      e₂ => mult  (optimize0plus e₁) (optimize0plus e₂)\n\n\n\n\nexample :\n    Aexp.optimize0plus (.plus (.num 2)\n                               (.plus (.num 0)\n                                      (.plus (.num 0) (.num 1))))\n      = .plus (.num 2) (.num 1) := by rfl\n\n\n\n\ntheorem optimize0plus_sound (a : Aexp) :\n    a.optimize0plus.eval = a.eval := by\n  induction a with\n  | num n => rfl\n  | plus a₁ a₂ ih₁ ih₂ =>\n    cases a₁ with\n    | num n =>\n      cases n with\n      | zero =>\n        simp only [optimize0plus, eval_plus, eval_num, Nat.zero_add]\n        exact ih₂\n      | succ n =>\n        simp only [optimize0plus, eval_plus, eval_num]\n        rw [ih₂]\n    | plus b₁ b₂ =>\n      simp only [optimize0plus, eval_plus] at ih₁ ⊢\n      rw [ih₁, ih₂]\n    | minus b₁ b₂ =>\n      simp only [optimize0plus, eval_plus] at ih₁ ⊢\n      rw [ih₁, ih₂]\n    | mult b₁ b₂ =>\n      simp only [optimize0plus, eval_plus] at ih₁ ⊢\n      rw [ih₁, ih₂]\n  | minus a₁ a₂ ih₁ ih₂ =>\n    simp only [optimize0plus, eval_minus]\n    rw [ih₁, ih₂]\n  | mult a₁ a₂ ih₁ ih₂ =>\n    simp only [optimize0plus, eval_mult]\n    rw [ih₁, ih₂]\n\n\n\n\nThe fun_induction tactic\ninducts along a function's own recursion structure:\nfun_induction Aexp.optimize0plus a hands us one goal per branch of optimize0plus — the\nspecial plus (num 0) e branch included — so the nested cases disappear.\n\n\n\ndef Nat.even (n : Nat) :=\n  match n with\n  | 0 => true\n  | 1 => false\n  | n' + 2 => even n'\n\ndef Nat.odd (n : Nat) := Nat.even (n + 1)\n\n\n\n\nexample (n : Nat) (h : Nat.even n = true) : Nat.odd n = false := by\n  sorry\n\n\n\n\nWe can use fun_induction to achieve a much shorter proof.\n\ntheorem optimize0plus_sound' (a : Aexp) :\n    a.optimize0plus.eval = a.eval := by\n  fun_induction Aexp.optimize0plus a <;> simp_all\n\nend Aexp\n\n\n\n\n\n\n","context":"Hoare Logic\u0009Slang: Arithmetic and Boolean Expressions\u0009Arithmetic and Boolean Expressions","header":"2.1.3. Optimization","id":"/Slang/#Hoare-Logic--Slang___-Arithmetic-and-Boolean-Expressions--Arithmetic-and-Boolean-Expressions--Optimization"}});